import{_ as a}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as r,o as e,af as o}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const u=JSON.parse('{"title":"学习路径","description":"按你现在卡在哪选路：先会用助手，再接到自己的应用，再上线。","frontmatter":{"title":"学习路径","description":"按你现在卡在哪选路：先会用助手，再接到自己的应用，再上线。","domain":"path","tags":["path"],"listed":false,"outline":false,"pageClass":"catalog-page","prev":false,"next":{"text":"路径 1 · 使用 AI 工具","link":"/zh/paths/productivity"}},"headers":[],"relativePath":"zh/paths/index.md","filePath":"zh/paths/index.md","lastUpdated":1791165915000}'),n={name:"zh/paths/index.md"};function i(s,t,h,l,d,p){return e(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="学习路径" tabindex="-1">学习路径 <a class="header-anchor" href="#学习路径" aria-label="Permalink to &quot;学习路径&quot;">​</a></h1><p>先回答一件事：<strong>你现在最痛的是哪一句？</strong></p><ol><li>「写代码太慢，助手在那不会用」→ 路径 1</li><li>「要把模型接到自己的产品里」→ 路径 2</li><li>「功能能跑，但不敢上线、算不清成本」→ 路径 3</li></ol><p>三条路是<strong>累计</strong>的，不是三个平行专题。默认 1 → 2 → 3。已经每天在用编码助手的人，可以从 2 进。</p><p><strong>不是</strong>产品说明书（去 <a href="/zh/products/">产品</a>），也不是模型内部怎么算（去 <a href="https://llm.zenheart.site/" target="_blank" rel="noreferrer">Learn LLM</a>）。</p><h2 id="三条路-按阅读顺序" tabindex="-1">三条路，按阅读顺序 <a class="header-anchor" href="#三条路-按阅读顺序" aria-label="Permalink to &quot;三条路，按阅读顺序&quot;">​</a></h2><h3 id="_1-使用-ai-工具" tabindex="-1">1. 使用 AI 工具 <a class="header-anchor" href="#_1-使用-ai-工具" aria-label="Permalink to &quot;1. 使用 AI 工具&quot;">​</a></h3><p><strong>问题</strong>：还在手写样板、自己翻文档、调试耗一下午。<br><strong>做完能干什么</strong>：在编辑器 / 终端里指挥 Cursor、Copilot、Claude、Gemini，让日常开发先快起来。<br><strong>下一步</strong>：有了手感，再把模型接到产品里。</p><p><strong><a href="/zh/paths/productivity.html">开始路径 1</a></strong></p><h3 id="_2-添加-ai-功能" tabindex="-1">2. 添加 AI 功能 <a class="header-anchor" href="#_2-添加-ai-功能" aria-label="Permalink to &quot;2. 添加 AI 功能&quot;">​</a></h3><p><strong>问题</strong>：助手会用了，但自己的 React / Vue 应用里还没有聊天、搜索、补全。<br><strong>做完能干什么</strong>：调 API、做流式 UI、上 RAG 搜索。<br><strong>前提</strong>：路径 1 的工具手感；会 TypeScript。</p><p><strong><a href="/zh/paths/integration.html">开始路径 2</a></strong></p><h3 id="_3-构建-ai-产品" tabindex="-1">3. 构建 AI 产品 <a class="header-anchor" href="#_3-构建-ai-产品" aria-label="Permalink to &quot;3. 构建 AI 产品&quot;">​</a></h3><p><strong>问题</strong>：Demo 能秀，生产环境超时、账单炸、没有评估。<br><strong>做完能干什么</strong>：部署、限流、监控、算成本、写评估。<br><strong>前提</strong>：路径 2 里至少做过一个能跑的功能。</p><p><strong><a href="/zh/paths/mastery.html">开始路径 3</a></strong></p><h2 id="怎么选-一张表" tabindex="-1">怎么选（一张表） <a class="header-anchor" href="#怎么选-一张表" aria-label="Permalink to &quot;怎么选（一张表）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>你现在的情况</th><th>走哪条</th></tr></thead><tbody><tr><td>几乎没认真用过编码助手</td><td>路径 1</td></tr><tr><td>每天在用助手，要给现有应用加能力</td><td>路径 2</td></tr><tr><td>已经接过 API / RAG，要上线</td><td>路径 3</td></tr><tr><td>产品经理，只想判断能力边界</td><td>先读路径 1 的决策部分，再看 <a href="/zh/practice/">企业实践</a></td></tr></tbody></table><h2 id="建议节奏" tabindex="-1">建议节奏 <a class="header-anchor" href="#建议节奏" aria-label="Permalink to &quot;建议节奏&quot;">​</a></h2><ul><li>路径 1：1–2 周，每天在真实仓库里用</li><li>路径 2：2–4 周，做出一个流式功能</li><li>路径 3：按上线清单走，不设死周数</li></ul><p>机制（为什么 prompt 这样写、RAG 为什么能减轻幻觉）链到 <a href="/zh/tech/">技术</a> 和 Learn LLM，本栏只负责「按什么顺序做」。</p>',20)])])}const _=a(n,[["render",i]]);export{u as __pageData,_ as default};
